(function(){
'use strict';
const C=window.LEARNING_CONTENT, KEY='ipa-mindmap-lab-v2';
const defaults=()=>({quiz:{},labs:{},micros:{},work:{},sim:{}});
let P;try{P=Object.assign(defaults(),JSON.parse(localStorage.getItem(KEY)||'{}'))}catch(e){P=defaults()}
for(const k of Object.keys(defaults()))if(!P[k]||typeof P[k]!=='object'||Array.isArray(P[k]))P[k]={};
let VIDEO_CONFIG={};
let UI={page:'home',quizIndex:0,lab:'meeting',labStep:0,reviewed:false,micro:'01',microStage:'watch',picked:null,checkedChoice:null,navOpen:{m1:true,m2:false,m3:false},stack:[],cardIndex:0,matchSource:null};
const $=sel=>document.querySelector(sel), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(P))}catch(e){}};
const message=s=>{const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(message.t);message.t=setTimeout(()=>t.classList.remove('show'),2600)};
const cnt=o=>Object.values(o||{}).filter(Boolean).length;
const lab=id=>(P.work[id] ||= {}), sim=id=>(P.sim[id] ||= {});
UI.quizResult=Object.keys(P.quiz).length===5;
const icon=(ch)=>`<span aria-hidden="true">${ch}</span>`;
const btn=(label,action,cls='primary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(label,kind='')=>`<span class="pill ${kind}">${label}</span>`;
const progress=(n,max)=>`<div class="progress-row"><span>Tiến độ</span><span class="mono">${n}/${max}</span></div><div class="progress-track"><div class="progress-bar" style="width:${n/max*100}%"></div></div>`;
function mapDrawing(root, branches, caption='MINDMAP · PREVIEW'){
 let out=`<div class="map-surface"><div class="map-layout"><div class="map-root">${esc(root)}</div><div class="map-branches">`;
 (branches||[]).forEach(b=>{const leaves=b.children||[];out+=`<div class="map-branch ${leaves.length?'':'no-leaves'}"><div class="branch-name">${esc(b.name)}</div>${leaves.length?`<div class="map-leaves">${leaves.map(x=>{const node=typeof x==='string'?{text:x}:x;const cls=/^(correct|incorrect|gold|focus)$/.test(node.style||'')?node.style:'';return `<span class="map-leaf ${cls}">${esc(node.text)}${cls==='incorrect'?'<small> · Cần sửa</small>':cls==='correct'?'<small> · Phù hợp</small>':''}</span>`}).join('')}</div>`:''}</div>`});
 return out+`</div></div></div>`;
}
function mapVisual(root,branches,caption){return canvas(root,branches,caption||'SƠ ĐỒ THAM KHẢO')}
function workPanel(title,content,tip='') {return `<section class="card pad"><div class="workspace-title">${esc(title)}</div>${content}${tip?`<p class="note item-space">${tip}</p>`:''}</section>`}
function shell(title,sub,kicker='LEARNING EXPERIENCE'){return `<div class="section-top"><span class="eyebrow">${kicker}</span><h2 style="margin:8px 0">${title}</h2><p class="subtitle">${sub}</p></div>`}
function snapshot(){return {page:UI.page,lab:UI.lab,labStep:UI.labStep,micro:UI.micro,microStage:UI.microStage,quizIndex:UI.quizIndex,cardIndex:UI.cardIndex,compare:UI.compare}}
function restore(v){Object.assign(UI,v);UI.reviewed=false;UI.checkedChoice=null;UI.picked=null;UI.matchSource=null;closeMap();setMenu(false);render();window.scrollTo({top:0,behavior:'instant'})}
function navigate(page,opts={}){
 if(!opts.noPush){UI.stack.push(snapshot());if(UI.stack.length>50)UI.stack.shift()}
 Object.assign(UI,opts.state||{});UI.page=page;UI.reviewed=false;UI.picked=null;UI.checkedChoice=null;UI.matchSource=null;closeMap();setMenu(false);
 if(page==='m1'||page==='m1video')UI.navOpen.m1=true;
 if(page==='m1quiz')UI.navOpen.m1=true;
 if(['m2','lab'].includes(page))UI.navOpen.m2=true;
 if(['m3','micro'].includes(page))UI.navOpen.m3=true;
 $('#sidebar').classList.remove('open'); render();window.scrollTo({top:0,behavior:'instant'});
}
function back(){const last=UI.stack.pop();if(last)restore(last);else navigate('home',{noPush:true})}
function crumbs(){const isHome=UI.page==='home';document.body.dataset.page=UI.page;$('.back-link').hidden=isHome;let path=isHome?[]:[{t:'Trang chủ',act:'open-home'}];
 if(['m1','m1video','m1quiz'].includes(UI.page)){path.push({t:'Module 1 · WHY & WHEN',act:'open-m1video'});if(UI.page==='m1quiz')path.push({t:'Quiz',act:'open-m1quiz'})}
 if(['m2','lab'].includes(UI.page)){path.push({t:'Module 2 · HOW',act:'open-m2'});if(UI.page==='lab'){let sc=C.scenarios.find(x=>x.id===UI.lab);path.push({t:sc?.title||'Tình huống',act:'open-current-lab'});path.push({t:'Bước '+(UI.labStep+1),act:'noop'})}}
 if(['m3','micro'].includes(UI.page)){path.push({t:'Module 3 · GITMIND',act:'open-m3'});if(UI.page==='micro')path.push({t:`3.${Number(UI.micro)} · ${C.micros.find(x=>x.id===UI.micro)?.title}`,act:'noop'})}
 $('#breadcrumb').innerHTML=path.map((x,i)=>`${i?'<span class="crumb-sep">›</span>':''}<button class="crumb ${i===path.length-1?'current':''}" data-global-action="${x.act}" ${i===path.length-1?'aria-current="page" disabled':''}>${esc(x.t)}</button>`).join('');
}
function navGroup(id,title,subtitle,entries){return `<div class="nav-group"><button class="nav-parent ${(['m1','m1video','m1quiz'].includes(UI.page)&&id==='m1')||(['m2','lab'].includes(UI.page)&&id==='m2')||(['m3','micro'].includes(UI.page)&&id==='m3')?'selected':''}" data-global-action="toggle-nav" data-id="${id}" aria-expanded="${UI.navOpen[id]?'true':'false'}"><span class="nav-parent-icon">${id==='m1'?'01':id==='m2'?'02':'03'}</span><span class="nav-parent-copy"><strong>${title}</strong><small>${subtitle}</small></span><span class="nav-chevron">⌄</span></button>${UI.navOpen[id]?`<div class="nav-children">${entries.map(x=>`<button class="nav-child ${x.active?'active':''}" data-global-action="${x.act}" ${x.id?`data-id="${x.id}"`:''}>${x.num?`<span class="nav-child-num">${x.num}</span>`:''}<span>${esc(x.title)}</span>${x.done?'<span class="nav-done">✓</span>':''}</button>`).join('')}</div>`:''}</div>`}
function renderNav(){
 const e1=[{num:'1.1',title:'Video bài học',act:'open-m1video',active:UI.page==='m1video'||UI.page==='m1'},{num:'1.2',title:'Quiz · 5 câu hỏi',act:'open-m1quiz',active:UI.page==='m1quiz',done:Object.keys(P.quiz).length===5}];
 const e2=[{num:'2.0',title:'Giới thiệu 5 tình huống',act:'open-m2',active:UI.page==='m2'},...C.scenarios.map((v,i)=>({num:`2.${i+1}`,title:v.title,act:'open-lab',id:v.id,active:UI.page==='lab'&&UI.lab===v.id,done:!!P.labs[v.id]}))];
 const e3=C.micros.map((v,i)=>({num:`3.${i+1}`,title:v.title,act:'open-micro',id:v.id,active:UI.page==='micro'&&UI.micro===v.id,done:!!P.micros[v.id]}));
 $('#side-nav').innerHTML=`${navGroup('m1','WHY & WHEN','Video & Quiz',e1)}${navGroup('m2','HOW TO THINK','5 bài thực hành',e2)}${navGroup('m3','GITMIND PRACTICE','6 kỹ năng Watch → Try → Check',e3)}`;
}
function render(){const views={home:homeView,m1:m1VideoView,m1video:m1VideoView,m1quiz:m1QuizView,m2:m2View,lab:labView,m3:m3View,micro:microView};$('#screen').innerHTML=(views[UI.page]||homeView)();renderNav();crumbs();bindVideo();$('#screen').classList.remove('page-enter');void $('#screen').offsetWidth;$('#screen').classList.add('page-enter');}
function homeView(){const q=Object.keys(P.quiz).length;const modules=[['01','WHY & WHEN','Hiểu khi nào dùng MindMap trong năm tình huống công việc.','m1',`${q}/5 câu hỏi`],['02','HOW TO THINK','Thực hành cấu trúc thông tin với năm scenario labs.','m2',`${cnt(P.labs)}/5 tình huống`],['03','GITMIND PRACTICE','Xem micro-video và thao tác lại trong simulator.','m3',`${cnt(P.micros)}/6 kỹ năng`]];
 return `<section class="hero"><img class="hero-image" src="assets/images/ipa-building.png" alt="" aria-hidden="true"><div class="hero-copy"><span class="eyebrow">IPA GROUP · INTERNAL LEARNING</span><h1>MindMap<br><span>as a Skill.</span></h1><p>Tư duy rõ ràng hơn. Kết nối thông tin tốt hơn. Biến những tình huống công việc thường ngày thành một bức tranh dễ hiểu và có thể hành động.</p><div class="btn-row">${btn('Bắt đầu hành trình →','open-m1','primary')}${btn('Khám phá tình huống','open-m2','outline')}</div></div><div class="hero-stat"><strong>03</strong><span>Modules</span><strong style="margin-top:20px">05</strong><span>Workplace scenarios</span></div></section>
 <div class="section-heading"><div><h2>Hành trình học tập</h2><p>Learn when · Learn how · Practice the tool</p></div>${tag('Learning by doing','gold')}</div>
 <section class="module-grid">${modules.map(m=>`<article class="module-card card"><div class="module-n">MODULE ${m[0]}</div><h3>${m[1]}</h3><p>${m[2]}</p><div class="mini-meta"><span class="pill">${m[4]}</span>${btn('Khám phá →','open-'+m[3],'ghost small')}</div></article>`).join('')}</section>
 <div class="learning-strip"><div style="font-size:1.6rem;color:var(--ipa-deep)">✧</div><div><strong>Tinh thần khóa học</strong><p>MindMap không phải chỉ là một hình vẽ đẹp. Mỗi sơ đồ cần trả lời đúng câu hỏi, làm rõ cấu trúc thông tin và giúp chúng ta tiến lên bước tiếp theo.</p></div></div>`;
}
function m1VideoView(){return shell('WHY & WHEN — Khi nào nên dùng MindMap?','Xem video bài học. Khi hoàn thành, tiếp tục với 5 câu hỏi tình huống để củng cố cách ứng dụng.','MODULE 01 · 1.1 VIDEO LEARNING')+
 `<section class="card pad-lg video-lesson"><div class="workspace-title">VIDEO BÀI HỌC · MINDMAP AS A SKILL</div><div class="video-wrap"><video controls preload="metadata" playsinline src="assets/videos/module-1/module-01.mp4" aria-label="MindMap as a Skill - Module 1"></video></div><p class="caption">Video nguồn gốc 1920×1080 · 03:59. Có thể mở toàn màn hình bằng nút trên trình phát.</p><div class="btn-row end">${btn('Tiếp tục: Quiz tương tác →','open-m1quiz')}</div></section>`}
function m1QuizView(){const qi=UI.quizIndex,item=C.quiz[qi],answered=P.quiz[qi]!==undefined,sel=P.quiz[qi],complete=Object.keys(P.quiz).length===5&&UI.quizResult;
 return shell('Quiz tình huống — WHY & WHEN','Ứng dụng nội dung vừa học để lựa chọn cách dùng MindMap phù hợp trong công việc.','MODULE 01 · 1.2 INTERACTIVE QUIZ')+
 `<section id="quiz" class="card pad-lg quiz-wrap">${complete?`<div class="progress-row"><span>QUIZ · KẾT QUẢ</span>${tag('Đã trả lời 5/5','complete')}</div><h3>Hoàn thành Quiz Module 1</h3><p>Kết quả: <strong>${C.quiz.filter((x,i)=>P.quiz[i]===x.answer).length}/5 câu phù hợp</strong>. Tiếp theo, bạn sẽ thực hành năm tình huống công việc trong Module 2.</p><div class="btn-row">${btn('Sang Module 2 →','open-m2')}${btn('Làm lại Quiz','reset-quiz','outline')}</div>`:
 `<div class="quiz-num">CÂU HỎI ${qi+1} / 5</div>${progress(qi+1,5)}<h3 class="quiz-question">${esc(item.q)}</h3><div class="options-list">${item.options.map((opt,i)=>`<button class="option-btn ${answered?(i===item.answer?'correct':i===sel?'wrong':''):(sel===i?'selected':'')}" data-action="quiz-answer" data-value="${i}" ${answered?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(opt)}</span></button>`).join('')}</div>${answered?`<div class="feedback ${sel===item.answer?'positive':''}"><strong>${sel===item.answer?'✓ Phù hợp':'Gợi ý điều chỉnh'}</strong><p>${esc(item.why)}</p></div><div class="btn-row end">${btn(qi===4?'Xem kết quả →':'Câu tiếp theo →','quiz-next')}</div>`:'<p class="note item-space">Chọn phương án và xem giải thích trước khi tiếp tục.</p>'}`}</section>`;
}
function m2View(){return shell('HOW TO THINK — Năm tình huống, năm cách lập sơ đồ','Bắt đầu từ mục đích công việc. Sau đó chọn cấu trúc thông tin phù hợp thay vì cố áp dụng một mẫu MindMap cho mọi trường hợp.','MODULE 02 · INTERACTIVE SCENARIO LABS')+
 `<div class="learning-strip" style="margin:0 0 22px"><div style="font-size:1.7rem;color:var(--ipa-deep)">◎</div><div><strong>Cùng công cụ — khác mục đích tư duy</strong><p>Học theo nhịp: Quan sát tình huống → Ra quyết định → Nhìn sơ đồ thay đổi → Nhận phản hồi → Chuyển sang công việc tiếp theo.</p></div></div><section class="scenario-grid">${C.scenarios.map(s=>`<button class="scenario-card" data-action="open-lab" data-id="${s.id}"><span class="scenario-icon">${s.icon}</span><strong>${s.num} · ${s.title}</strong><small>${s.subtitle}</small><span class="scenario-bottom">${P.labs[s.id]?'✓ Đã hoàn thành':'Bắt đầu tình huống'} <span>↗</span></span></button>`).join('')}</section><div class="card pad item-space"><div class="progress-row"><span>Tiến độ Module 2</span><span>${cnt(P.labs)}/5 labs</span></div><div class="progress-track"><div class="progress-bar" style="width:${cnt(P.labs)*20}%"></div></div><p class="note item-space">Các tình huống đều là ví dụ giả định để luyện kỹ năng; không phản ánh quy trình hay chính sách đã được ban hành của IPA Group.</p><div class="btn-row end">${btn('Tiếp tục Module 3 →','open-m3','outline')}</div></div>`}
const meetings=[['Finance đã đồng ý ngân sách','Decision'],['Mai sẽ gửi bản cập nhật vào thứ Sáu','Action'],['Pháp chế cần rà soát nội dung cuối','Action'],['Chưa rõ IT có cần tham gia hay không','Open Question']];
const issueData=[['Ba kỳ gần nhất báo cáo nộp muộn','Fact'],['Mẫu báo cáo thay đổi vào tháng trước','Fact'],['Hệ thống mới chắc chắn gây chậm','Hypothesis'],['Chưa có người nhận trách nhiệm tổng hợp','Hypothesis']];
const projectData=[['Mục tiêu và kết quả kỳ vọng',1],['Phạm vi trong / ngoài dự án',1],['Các bên liên quan và vai trò',1],['Các nhóm công việc chính',1],['Rủi ro và ràng buộc',1],['Thiết kế banner ngay ngày mai',0],['Gửi email mời họp đầu tiên',0]];
const pictureData=[['Mục tiêu dự án',1],['Tiến độ hiện tại',1],['Rủi ro trọng yếu',1],['Quyết định cần phê duyệt',1],['Mốc tiếp theo',1],['Lịch hẹn vendor lần thứ 4',0],['Chi tiết 17 comment của team',0],['Thứ tự các email nhắc việc',0]];
const decisionData=[['Đào tạo trực tiếp','Option'],['E-learning','Option'],['Chi phí','Criterion'],['Thời gian triển khai','Criterion'],['Finance muốn tối ưu ngân sách','Perspective'],['Business lo ảnh hưởng lịch làm việc','Perspective']];
function rowActivity(items,id,options){
 const w=lab(id),selected=UI.picked;
 return `<div class="interaction-guide"><span class="tiny-dot"></span> Kéo thẻ vào nhóm phù hợp, hoặc click một thẻ rồi click nhóm. Có thể thay đổi lựa chọn trước khi nhận phản hồi.</div>
 <div class="classify-board"><div class="classify-cards" aria-label="Các thẻ thông tin">${items.map((it,i)=>{
 const v=(w.rows||{})[i],status=UI.reviewed?(v===it[1]?'right':'wrong'):'';
 return `<button type="button" draggable="true" class="info-chip ${selected===i?'picked':''} ${status}" data-action="choose-chip" data-index="${i}" data-drag-chip="${i}" aria-pressed="${selected===i}"><span class="chip-num">${String(i+1).padStart(2,'0')}</span><span class="chip-content">${esc(it[0])}<small>${v?`Đang ở: ${esc(v)}`:'Chưa phân loại'}</small>${UI.reviewed?`<em class="item-verdict ${status}">${status==='right'?'✓ Phù hợp':`↻ Gợi ý: ${esc(it[1])}`}</em>`:''}</span><span class="grip">⠿</span></button>`}).join('')}</div>
 <div class="drop-targets" aria-label="Nhóm thông tin">${options.map((o,j)=>`<button type="button" class="drop-target ${selected!==null?'ready':''}" data-action="assign-chip" data-category="${esc(o)}" data-drop-category="${esc(o)}"><strong>${esc(o)}</strong><small>${items.filter((it,i)=>(w.rows||{})[i]===o).length} mục · Thả hoặc click</small></button>`).join('')}</div></div>`;
}
function reviewRows(items,id,groups){const w=lab(id),n=items.filter((it,i)=>(w.rows||{})[i]===it[1]).length;
 return `<div class="review-card"><div class="review-head"><div><strong>Phản hồi theo từng thẻ</strong><p>Đối chiếu với một phương án tham khảo. Click thẻ và chọn nhóm khác để chỉnh sửa.</p></div><span class="review-score">${n}/${items.length}</span></div><div class="review-items">${items.map((it,i)=>{const v=(w.rows||{})[i];return `<div class="review-item ${v===it[1]?'right':'wrong'}"><span class="review-icon">${v===it[1]?'✓':'↻'}</span><div><strong>${esc(it[0])}</strong><small>Bạn chọn: ${esc(v||'Chưa phân loại')} · ${v===it[1]?'Phù hợp':`Gợi ý: ${esc(it[1])}`}</small></div></div>`}).join('')}</div><div class="reference-title">MINDMAP GỢI Ý SAU PHẢN HỒI</div>${mapVisual(id==='meeting'?'Họp triển khai':id==='problem'?'Báo cáo trễ':'Hình thức đào tạo',groups.map(c=>({name:c,children:items.filter(it=>it[1]===c).map(it=>({text:it[0],style:'correct'}))})), 'BẢN THAM KHẢO · CÓ THỂ ĐIỀU CHỈNH THEO CONTEXT')}</div>`;
}
function userMap(items,id,groups){const w=lab(id);return mapVisual(id==='meeting'?'Họp triển khai':id==='problem'?'Báo cáo trễ':'Hình thức đào tạo',groups.map(c=>({name:c,children:items.filter((it,i)=>(w.rows||{})[i]===c).map(it=>({text:it[0],style:UI.reviewed?(it[1]===c?'correct':'incorrect'):''}))})),UI.reviewed?'CÁC NODE ĐƯỢC ĐÁNH DẤU THEO PHẢN HỒI':'MINDMAP · CẬP NHẬT KHI PHÂN LOẠI');}
function chooseCards(items,id){const w=lab(id);return `<div class="check-grid">${items.map((x,i)=>`<button class="select-card ${(w.selected||[]).includes(i)?'on':''}" data-action="lab-toggle" data-index="${i}" aria-pressed="${(w.selected||[]).includes(i)}">${esc(x[0])}</button>`).join('')}</div>`}
function radioCards(options,id){const w=lab(id);return `<div class="options-list">${options.map((x,i)=>`<button class="option-btn ${(w.choices||{})[UI.labStep]===i?'selected':''}" data-action="lab-choice" data-index="${i}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(x)}</span></button>`).join('')}</div>`}
function labFeedback(text,heading='Góc nhìn thực hành'){return `<div class="feedback ${UI.reviewed?'':'warn'}"><strong>${heading}</strong><p>${text}</p></div>`}
function canvas(root,branches,caption='SƠ ĐỒ CỦA BẠN'){
 return `<section class="canvas-panel"><div class="canvas-tools"><strong>${esc(caption)}</strong><div class="canvas-controls"><button class="outline small" data-action="map-zoom" data-delta="-0.15" aria-label="Thu nhỏ sơ đồ">−</button><button class="outline small" data-action="map-fit">100%</button><button class="outline small" data-action="map-zoom" data-delta="0.15" aria-label="Phóng to sơ đồ">+</button><button class="outline small" data-action="map-expand">⛶ Phóng toàn màn hình</button></div></div><div class="canvas-viewport" tabindex="0" aria-label="Sơ đồ; cuộn để xem các nhánh"><div class="zoom-content">${mapDrawing(root,branches,caption)}</div></div></section>`;
}
function rowMap(id){const d=C.activities[id],w=lab(id);return canvas(d.root,d.groups.map(g=>({name:g,children:d.items.filter((x,i)=>w.rows?.[i]===g).map(x=>({text:x[0],style:UI.reviewed?(x[1]===g?'correct':'incorrect'):''}))})));}
function explainRows(id){const d=C.activities[id],w=lab(id),n=d.items.filter((x,i)=>w.rows?.[i]===x[1]).length;return `<section class="review-card" role="status"><div class="review-head"><strong>Đối chiếu từng thông tin</strong><span class="review-score">${n}/${d.items.length}</span></div><div class="review-items">${d.items.map((x,i)=>`<div class="review-item ${w.rows?.[i]===x[1]?'right':'wrong'}"><span class="review-icon">${w.rows?.[i]===x[1]?'✓':'↻'}</span><div><strong>${esc(x[0])}</strong><small>Bạn chọn: ${esc(w.rows?.[i]||'Chưa chọn')} · Gợi ý: ${esc(x[1])}</small><p>${esc(x[2])}</p></div></div>`).join('')}</div><p class="note item-space">Đây là phương án tham khảo dựa trên dữ kiện của bài. Bạn có thể sửa lựa chọn và nhận phản hồi lại.</p></section>`;}
function meetingActivity(){const d=C.activities.meeting,w=lab('meeting'),i=Math.min(UI.cardIndex,d.items.length-1),x=d.items[i],n=Object.keys(w.rows||{}).length;
 return `<div class="activity-intro"><span class="activity-tag">01 · Phân loại từng thẻ</span><p>Đọc một thông tin, chọn nhánh phù hợp. Không cần kéo thả.</p></div><div class="focus-card"><div class="card-counter">THÔNG TIN ${i+1} / ${d.items.length} · ${n} ĐÃ PHÂN LOẠI</div><h3>${esc(x[0])}</h3><div class="category-choices">${d.groups.map(g=>`<button class="category-choice ${w.rows?.[i]===g?'selected':''}" data-action="card-assign" data-category="${g}" data-index="${i}" aria-pressed="${w.rows?.[i]===g}">${g}<small>${{Decision:'Quyết định',Action:'Hành động','Open Question':'Câu hỏi mở',Risk:'Rủi ro'}[g]}</small></button>`).join('')}</div><div class="card-pagination">${d.items.map((x,j)=>`<button class="card-dot ${i===j?'current':''} ${w.rows?.[j]?'done':''}" data-action="card-page" data-index="${j}" aria-label="Thông tin ${j+1}" aria-current="${i===j?'step':'false'}">${w.rows?.[j]?'✓':j+1}</button>`).join('')}<span>Chọn số để xem lại hoặc chỉnh sửa</span></div></div>${rowMap('meeting')}${UI.reviewed?explainRows('meeting'):''}`;
}
function problemActivity(){const d=C.activities.problem,w=lab('problem');return `<div class="activity-intro"><span class="activity-tag">02 · Thám tử dữ kiện</span><p>Đánh dấu từng phát biểu: điều quan sát được hay giải thích cần kiểm chứng?</p></div><div class="evidence-board">${d.items.map((x,i)=>`<article class="evidence-card"><span class="card-counter">PHÁT BIỂU ${i+1}</span><h3>${esc(x[0])}</h3><div class="segmented">${d.groups.map(g=>`<button class="${w.rows?.[i]===g?'selected':''}" data-action="evidence-assign" data-index="${i}" data-category="${g}" aria-pressed="${w.rows?.[i]===g}">${g==='Fact'?'◉ Dữ kiện':'? Giả thuyết'}</button>`).join('')}</div></article>`).join('')}</div>${rowMap('problem')}${UI.reviewed?explainRows('problem'):''}`;}
function selectionReview(id){const d=C.activities[id],w=lab(id),sel=w.selected||[],correct=d.items.filter((x,i)=>sel.includes(i)===!!x[1]).length;return `<section class="review-card" role="status"><div class="review-head"><strong>${id==='picture'?'Bản đồ cho người đọc':'Cấu trúc cấp cao của dự án'}</strong><span class="review-score">${correct}/${d.items.length}</span></div><div class="review-items">${d.items.map((x,i)=>`<div class="review-item ${sel.includes(i)===!!x[1]?'right':'wrong'}"><span class="review-icon">${sel.includes(i)===!!x[1]?'✓':'↻'}</span><div><strong>${esc(x[0])}</strong><small>Bạn ${sel.includes(i)?'giữ ở tầng đầu':'để ở tầng chi tiết'} · Gợi ý: ${x[1]?'giữ ở tầng đầu':'để ở tầng chi tiết'}</small><p>${esc(x[2])}</p></div></div>`).join('')}</div><p class="note item-space">Một cấu trúc tham khảo theo mục đích của tình huống; có thể điều chỉnh cho công việc thực tế.</p></section>`;}
function projectActivity(){const d=C.activities.project,w=lab('project'),sel=w.selected||[];return `<div class="activity-intro"><span class="activity-tag">03 · Xây nhánh dự án</span><p>Thêm các nhánh định hướng vào bản đồ. Để task chi tiết ở tầng sâu.</p></div><div class="branch-builder">${d.items.map((x,i)=>`<button class="branch-tile ${sel.includes(i)?'on':''}" data-action="lab-toggle" data-index="${i}" aria-pressed="${sel.includes(i)}"><span>${sel.includes(i)?'✓':'+'}</span><strong>${esc(x[0])}</strong><small>${sel.includes(i)?'Đã thêm · bấm để gỡ':'Bấm để thêm nhánh'}</small></button>`).join('')}</div>${canvas(d.root,sel.map(i=>({name:d.items[i][0]})),'BẢN ĐỒ KHỞI ĐỘNG DỰ ÁN')}${UI.reviewed?selectionReview('project'):''}`;}
function pictureActivity(){const d=C.activities.picture,w=lab('picture');w.selected ||= d.items.map((x,i)=>i);const sel=w.selected;return `<div class="activity-intro"><span class="activity-tag">04 · Biên tập sơ đồ</span><p>Bấm vào thông tin để chuyển xuống tầng chi tiết. Giữ bức tranh cần trình bày trong 30 giây.</p></div><div class="editor-toolbar"><strong>${sel.length} thông tin đang ở tầng đầu</strong>${btn(UI.compare?'Đóng bản gốc':'So sánh với bản gốc','picture-compare','outline small')}</div>${UI.compare?`<div class="reference-preview">${canvas(d.root,d.items.map(x=>({name:x[0]})),'BẢN GỐC · TẤT CẢ THÔNG TIN')}</div>`:''}<div class="prune-map"><div class="prune-root">CẬP NHẬT CHO LÃNH ĐẠO</div><div class="prune-nodes">${d.items.map((x,i)=>`<button class="prune-node ${sel.includes(i)?'kept':'archived'}" data-action="lab-toggle" data-index="${i}" aria-pressed="${sel.includes(i)}"><strong>${esc(x[0])}</strong><small>${sel.includes(i)?'● Tầng đầu · bấm để tinh gọn':'↳ Tầng chi tiết · bấm để khôi phục'}</small></button>`).join('')}</div></div>${canvas(d.root,sel.map(i=>({name:d.items[i][0]})),'EXECUTIVE VIEW · SAU BIÊN TẬP')}${UI.reviewed?selectionReview('picture'):''}`;}
function decisionActivity(){const d=C.activities.decision,w=lab('decision'),matches=w.matches||{};return `<div class="activity-intro"><span class="activity-tag">05 · Nối góc nhìn & tiêu chí</span><p>Chọn một góc nhìn, rồi chọn tiêu chí cần có bằng chứng để so sánh.</p></div><div class="matching-board"><div><h3>Góc nhìn các bên</h3>${d.views.map((x,i)=>`<button class="match-source ${UI.matchSource===i?'picked':''}" data-action="match-source" data-index="${i}" aria-pressed="${UI.matchSource===i}"><strong>${esc(x[0])}</strong><small>${matches[i]?'→ '+esc(matches[i]):'Chọn để nối tiêu chí'}</small></button>`).join('')}</div><div><h3>Tiêu chí so sánh</h3>${d.criteria.map(g=>`<button class="match-target" data-action="match-target" data-category="${esc(g)}" ${UI.matchSource===null?'disabled':''}>${esc(g)} <span>↗</span></button>`).join('')}</div></div>${canvas(d.root,[{name:'Phương án',children:['Trực tiếp','E-learning']},{name:'Tiêu chí',children:d.criteria},{name:'Góc nhìn → bằng chứng',children:d.views.map((x,i)=>({text:x[0]+' → '+(matches[i]||'Chưa nối'),style:UI.reviewed?(matches[i]===x[1]?'correct':'incorrect'):''}))}])}${UI.reviewed?`<section class="review-card" role="status"><strong>Góc nhìn cần được chuyển thành tiêu chí có thể so sánh</strong><div class="review-items item-space">${d.views.map((x,i)=>`<div class="review-item ${matches[i]===x[1]?'right':'wrong'}"><div><strong>${matches[i]===x[1]?'✓':'↻'} ${esc(x[0])}</strong><small>Bạn nối: ${esc(matches[i])} · Gợi ý: ${esc(x[1])}</small><p>${esc(x[2])}</p></div></div>`).join('')}</div></section>`:''}`;}
function evidenceReview(){const w=lab('problem'),sel=w.selected||[],items=[['Thời điểm yêu cầu / nhận dữ liệu',1,'Đối chiếu thời điểm nhận file với hạn tổng hợp để kiểm tra giả thuyết đầu vào muộn.'],['Các mốc xử lý và người chịu trách nhiệm',1,'Xác định điểm chờ và người xử lý trong quy trình.'],['Danh sách các màu đã dùng trong báo cáo',0,'Màu báo cáo không giúp kiểm tra đầu vào có đến muộn hay không.'],['Thời gian tổng hợp và số lần phải làm lại',1,'Phân biệt chậm do chờ đầu vào với chậm do thời gian xử lý và làm lại.']];return `<section class="review-card"><strong>Vì sao cần những bằng chứng này?</strong><div class="review-items item-space">${items.map((x,i)=>`<div class="review-item ${sel.includes(i)===!!x[1]?'right':'wrong'}"><div><strong>${sel.includes(i)===!!x[1]?'✓':'↻'} ${esc(x[0])}</strong><small>${sel.includes(i)?'Bạn chọn':'Bạn chưa chọn'} · ${x[1]?'Nên thu thập':'Không phục vụ giả thuyết này'}</small><p>${esc(x[2])}</p></div></div>`).join('')}</div></section>`;}
function labBody(id,step){const w=lab(id);
 if(id==='meeting'){
  if(step===0)return `<div class="context"><strong>Cuộc họp triển khai một hoạt động nội bộ</strong><p>Team đang rà soát ngân sách, chỉnh sửa tài liệu, vai trò của IT và deadline. Bạn phải ghi chú ngay trong lúc mọi người trao đổi.</p></div>${workPanel('QUAN SÁT MẪU','<p class="small-text">Một bản ghi thô có thể rất dài. Ví dụ: “Finance đã đồng ý ngân sách” nên trở thành một <b>Decision</b>, không phải một đoạn văn dài.</p>'+mapVisual('Họp triển khai',[{name:'Ngân sách',children:[{text:'D · Đã đồng ý',style:'gold'}]},{name:'Tài liệu',children:['A · Bản cập nhật']},{name:'Các câu hỏi',children:['IT có tham gia?']}]),'Trong cuộc họp, chưa cần bản đồ hoàn hảo.')}${labFeedback('Cấu trúc tạm thời vẫn tốt hơn chép mọi câu. Sau cuộc họp, bạn có thể chỉnh lại nhánh và xác nhận owner/deadline.','Quan sát để bắt đầu')}`;
  if(step===1)return meetingActivity();

  return `<div class="split equal">${workPanel('HOÀN THIỆN KẾT QUẢ CUỘC HỌP',`<p class="small-text">Một Action đủ dùng cần biết ai làm và khi nào. Hãy bổ sung thông tin cho việc cập nhật tài liệu.</p><label class="input-label" for="meeting-owner">Người thực hiện</label><input id="meeting-owner" class="input" type="text" value="${esc(w.owner||'Mai')}" data-field="meeting-owner"><label class="input-label item-space" for="meeting-date">Thời hạn</label><input id="meeting-date" class="input" type="text" value="${esc(w.deadline||'Thứ Sáu')}" data-field="meeting-deadline"><p class="note item-space">Trước khi gửi recap, hãy xác nhận lại owner, deadline và những điểm còn mở.</p>`)}${workPanel('MAP SAU CUỘC HỌP',mapVisual('Họp triển khai',[{name:'Ngân sách',children:['D · Budget approved']},{name:'Tài liệu',children:[`A · Bản cập nhật · ${w.owner||'Mai'} · ${w.deadline||'Thứ Sáu'}`,'A · Pháp chế rà soát']},{name:'IT',children:['Q · Có cần tham gia?']}]))}</div>${labFeedback('Sơ đồ này giúp nhìn nhanh kết quả cuộc họp. Với cuộc họp yêu cầu biên bản chính thức, vẫn phải tuân thủ định dạng biên bản được quy định.')}`;
 }
 if(id==='problem'){
  if(step===0)return `<div class="context"><strong>Vấn đề cần phân tích</strong><p>Báo cáo hàng tháng liên tục gửi trễ, nhiều bộ phận đưa ra nguyên nhân khác nhau. Trước khi vẽ nhánh, hãy xác định vấn đề trung tâm cụ thể.</p></div>${workPanel('CHỌN CÂU HỎI TRUNG TÂM',radioCards(['Tại sao mọi người làm việc không tốt?','Điều gì có thể dẫn tới việc báo cáo bị gửi trễ trong ba kỳ gần nhất?','Làm thế nào thay hệ thống hiện tại ngay lập tức?'],id))}${(w.choices||{})[step]!==undefined?labFeedback((w.choices||{})[step]===1?'Mô tả cụ thể hiện tượng cần khám phá, chưa mặc định một lời giải.':'Câu hỏi này đang suy đoán hoặc nhảy thẳng sang giải pháp. Nên bắt đầu bằng hiện tượng có thể quan sát được.') : ''}`;
  if(step===1)return problemActivity();

  return `<div class="context"><strong>Đào sâu nhưng chưa vội kết luận</strong><p>Một giả thuyết là “dữ liệu đầu vào gửi muộn”. Chúng ta cần gì để kiểm chứng?</p></div>${workPanel('CHỌN BẰNG CHỨNG CẦN THU THẬP',chooseCards([['Thời điểm yêu cầu / nhận dữ liệu',1],['Các mốc xử lý và người chịu trách nhiệm',1],['Danh sách các màu đã dùng trong báo cáo',0],['Thời gian tổng hợp và số lần phải làm lại',1]],id))}${mapVisual('Báo cáo trễ',[{name:'Process',children:['? Đầu vào đến muộn','? Yêu cầu dữ liệu quá sát hạn']},{name:'Evidence needed',children:['Timestamp nhận file','Lịch sử chốt đầu mối','Thời gian xử lý']}])}${UI.reviewed?evidenceReview()+labFeedback('Sơ đồ giúp tổ chức các giả thuyết để kiểm chứng. Không phải cứ hỏi “vì sao?” nhiều lần sẽ tự tìm được một nguyên nhân gốc duy nhất.'):''}`;
 }
 if(id==='project'){
  if(step===0)return `<div class="context"><strong>Đề bài</strong><p>“Quý sau, chúng ta cần triển khai chương trình chia sẻ kiến thức nội bộ.” Nhóm muốn bắt đầu làm ngay, nhưng chưa thống nhất như thế nào được xem là thành công.</p></div>${workPanel('ĐỊNH HƯỚNG CÂU HỎI TRUNG TÂM',radioCards(['Cần gửi email nào vào sáng mai?','Cần làm rõ những gì trước khi chương trình bắt đầu?','Ai làm slide đẹp nhất?'],id))}${(w.choices||{})[step]!==undefined?labFeedback((w.choices||{})[step]===1?'Câu hỏi này hướng tới project framing trước execution.':'Câu hỏi này quá hẹp hoặc đi thẳng vào đầu việc cụ thể.') : ''}`;
  if(step===1)return projectActivity();
  return `${workPanel('TÌM RANH GIỚI PHẠM VI',`<p class="small-text">Ví dụ: Dự án thí điểm trong một đơn vị. Chọn thông tin làm rõ ranh giới:</p>${radioCards(['In scope: một đơn vị thí điểm; Out of scope: triển khai toàn tập đoàn ngay','In scope: triển khai ngay cho toàn bộ tập đoàn mà không cần thử nghiệm'],id)}`)}${mapVisual('Chương trình thí điểm',[{name:'Why / Success',children:['Nâng cao chia sẻ kiến thức']},{name:'Scope',children:['Trong phạm vi: 1 đơn vị','Ngoài phạm vi: rollout toàn tập đoàn']},{name:'People',children:['Sponsor / Owner / Participants']},{name:'Work',children:['Thiết kế','Thí điểm','Đánh giá']}])}${UI.reviewed?labFeedback('Trong giai đoạn khởi động, mục tiêu/phạm vi/đầu mối cần thống nhất trước; sơ đồ không thay thế charter hoặc WBS chính thức nếu dự án yêu cầu.'):''}`;
 }
 if(id==='picture'){
  if(step===0)return `<div class="context"><strong>Tình huống</strong><p>Bạn cần trình bày trạng thái một dự án cho lãnh đạo trong 30 giây. Working map chứa mọi cuộc trao đổi, tài liệu và đầu việc từng phát sinh.</p></div>${mapVisual('Dự án LMS',[{name:'Tài liệu',children:['Bản thảo','17 comments','Checklist','Tệp đối tác']},{name:'Trao đổi',children:['Email nhắc 1','Email nhắc 2','Họp vendor']},{name:'Điều phối',children:['Timeline','Ngân sách','Testing','Rollout']}])}${labFeedback('Người tạo sơ đồ có thể cần nhiều chi tiết. Người nhận thông tin cần nhìn thấy bức tranh trả lời đúng câu hỏi của mình.')}`;
  if(step===1)return pictureActivity();
  return `${workPanel('SIGNAL THÔNG TIN CẦN HÀNH ĐỘNG',radioCards(['Highlight rủi ro và quyết định cần phê duyệt','Tô màu ngẫu nhiên cho tất cả các nhánh','Ẩn luôn các điểm cần quyết định'],id))}${mapVisual('Dự án LMS · Status',[{name:'Mục tiêu',children:['Rollout thí điểm']},{name:'Tiến độ',children:['Giai đoạn cấu hình']},{name:'Rủi ro',children:[{text:'! Thiếu dữ liệu chuyển đổi',style:'gold'}]},{name:'Cần quyết định',children:[{text:'Phê duyệt lộ trình',style:'focus'}]}])}${UI.reviewed?labFeedback('Một tín hiệu tốt giúp người đọc nhận ra điều quan trọng; nó không đơn thuần là thêm màu sắc.'):''}`;
 }
 if(id==='decision'){
  if(step===0)return `<div class="context"><strong>Tình huống</strong><p>L&D, Finance và Business cần thống nhất phương thức triển khai một chương trình đào tạo. Các bên ưu tiên những yếu tố khác nhau.</p></div>${workPanel('XÁC ĐỊNH CÂU HỎI QUYẾT ĐỊNH',radioCards(['Phương án nào nhìn đẹp hơn?','Nên chọn hình thức đào tạo nào để cân bằng trải nghiệm, thời gian và ngân sách?','Vì sao Finance luôn chọn phương án rẻ nhất?'],id))}${(w.choices||{})[step]!==undefined?labFeedback((w.choices||{})[step]===1?'Bạn đã xác định được quyết định cần giải quyết và các trade-off cần làm rõ.':'Một câu hỏi quyết định tốt không nên nghiêng sẵn về một bên hoặc chỉ xét một tiêu chí.'):''}`;
  if(step===1)return decisionActivity();

  return `${workPanel('MINDMAP ĐÃ ĐỦ ĐỂ QUYẾT ĐỊNH?',radioCards(['Có — phương án nào có nhiều node nhất thì thắng','Chưa chắc — cần bảng tiêu chí và bằng chứng để so sánh trade-off'],id))}${mapVisual('Quyết định hình thức',[{name:'Options',children:['Trực tiếp','E-learning','Blended']},{name:'Criteria',children:['Cost','Time','Learner experience']},{name:'Views / Evidence',children:['Finance','Business','L&D']},{name:'Next',children:['Decision Matrix']}])}${UI.reviewed?labFeedback('MindMap làm rõ cấu trúc quyết định, nhưng không thay thế ma trận so sánh đa tiêu chí khi các phương án có trade-off đáng kể.'):''}`;
 }
 return '';
}
function labView(){const s=C.scenarios.find(x=>x.id===UI.lab),step=UI.labStep,total=3,w=lab(s.id);if(s.id==='picture'&&step===1)w.selected ||= C.activities.picture.items.map((x,i)=>i);let ready=true;if((s.id==='meeting'||s.id==='problem')&&step===1){const num=(s.id==='meeting'?meetings:s.id==='problem'?issueData:decisionData).length;ready=Object.values(w.rows||{}).filter(Boolean).length===num}
 if(step===0&&['problem','project','decision'].includes(s.id))ready=(w.choices||{})[step]!==undefined;if(step===1&&['project','picture'].includes(s.id))ready=(w.selected||[]).length>0;
 if(step===2&&['picture','project','decision'].includes(s.id))ready=(w.choices||{})[step]!==undefined;
 if(step===1&&s.id==='decision')ready=Object.keys(w.matches||{}).length===C.activities.decision.views.length;if(step===2&&s.id==='problem')ready=(w.selected||[]).length>0;
 const info=step===0?'SEE · HIỂU TÌNH HUỐNG':step===1?'COMPLETE · THAO TÁC VỚI THÔNG TIN':'BUILD · HOÀN THIỆN SƠ ĐỒ';
 return `<div class="lab-header"><div><span class="eyebrow">MODULE 02 · LAB ${s.num} / 05</span><h2>${esc(s.title)}</h2><p class="subtitle" style="margin-bottom:0">${esc(s.outcome)}</p></div></div><div class="stepper">${['Quan sát mẫu','Tương tác cấu trúc','Hoàn thiện & ứng dụng'].map((x,i)=>`<div class="step ${i===step?'active':i<step?'done':''}"><b>${i<step?'✓':i+1}</b>${x}</div>`).join('')}</div><section class="lab-content"><div class="card pad-lg"><div class="lab-stage">${info}</div><div class="lab-stage-bar">${Array.from({length:3},(_,i)=>`<span class="${i<step?'done':i===step?'current':''}"></span>`).join('')}</div><div class="item-space">${labBody(s.id,step)}</div><div class="btn-row between">${step>0?btn('← Bước trước','lab-prev','outline'):btn('← Danh sách tình huống','open-m2','outline')}
 <div class="btn-row" style="margin-top:0">${step===0?btn('Tiếp tục →','lab-next','primary',ready?'':'disabled'):UI.reviewed?btn(step===2?'Hoàn thành tình huống ✓':'Bước tiếp theo →',step===2?'lab-finish':'lab-next'):btn('Nhận phản hồi →','lab-review','primary',ready?'':'disabled')}</div></div></div><div class="kicker"><strong>Nguyên tắc ứng dụng</strong> · ${esc(s.principle)}</div></section>`;
}
function m3View(){return shell('GITMIND PRACTICE — Watch → Try → Check','Sáu kỹ năng nền tảng được chia thành sáu bài con trong menu. Mỗi bài có video ngắn, thao tác mô phỏng và bước Check để xác nhận kỹ năng.','MODULE 03 · OVERVIEW')+
 `<div class="learning-strip"><span class="scenario-icon">▶</span><div><strong>Chọn bài học từ menu Module 3 bên trái</strong><p>Nếu video chưa sẵn sàng, bạn vẫn có thể bắt đầu thực hành. Phần Check tóm tắt thao tác và đưa ra một câu hỏi áp dụng.</p></div></div><div class="card pad-lg item-space"><h3>Đi theo trình tự Watch → Try → Check</h3><p>Mỗi bài giúp bạn thực hành một thao tác thiết yếu để tạo sơ đồ dùng được trong công việc.</p><div class="btn-row">${btn('Bắt đầu 3.1 · Khởi tạo MindMap →','start-micro')}</div>${progress(cnt(P.micros),6)}</div>`}
function youtubeId(url){try{const u=new URL(url);if(u.hostname==='youtu.be'||u.hostname==='www.youtu.be')return /^[A-Za-z0-9_-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(['youtube.com','www.youtube.com','m.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(u.hostname)){const id=u.searchParams.get('v')||(u.pathname.match(/\/(?:embed|shorts)\/([A-Za-z0-9_-]{11})/)||[])[1];return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null}}catch(e){}return null}
function microVideo(m){const v=VIDEO_CONFIG[m.id];const vid=v?.type==='youtube'?youtubeId(v.url):null;if(vid)return `<div class="video-wrap"><iframe loading="lazy" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube-nocookie.com/embed/${vid}?rel=0" title="GitMind Micro ${m.id}" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>`;return `<div class="video-wrap micro-video" data-micro-video="${m.id}"><video preload="metadata" playsinline controls aria-label="Hướng dẫn ${esc(m.title)}" src="assets/videos/module-3/${m.file}" data-micro-media="${m.id}"></video><div class="video-placeholder" hidden><span class="play-ring">▶</span><strong>Chờ video ${m.id}</strong><small>Hướng dẫn video đang được bổ sung. Bạn có thể chuyển sang TRY để thực hành ngay.</small></div></div>`}
function simMap(root,branches,relation=''){return `<div class="simulator"><div class="sim-toolbar"><span class="sim-caption">SƠ ĐỒ THỰC HÀNH · dùng các điều khiển bên dưới</span></div><div class="sim-canvas">${mapVisual(root,branches,'SIMULATOR · GITMIND-LIKE CANVAS')}${relation?`<div class="kicker item-space">⇢ ${esc(relation)}</div>`:''}</div>`}
function microTry(id){const w=sim(id);let v='';
 if(id==='01') {v=`${simMap(w.root||'New MindMap',[])}<div class="sim-actions"><p><strong>TRY:</strong> đặt tên Central Topic cho một cuộc họp.</p><div class="sim-inline"><input class="input" style="flex:1" id="sim-root" aria-label="Tên chủ đề trung tâm" type="text" maxlength="90" placeholder="VD: Họp triển khai đào tạo Q4" value="${esc(w.root||'')}">${btn('Áp dụng tên','sim-root-apply','primary small')}</div>${w.completed?`<div class="sim-notice">✓ Chủ đề trung tâm đã thay đổi. Đây là thao tác được luyện, không phải bài chấm điểm.</div>`:''}</div></div>`}
 if(id==='02'){const branches=w.branches||[{name:'Timeline',children:[]}];v=`${simMap('Họp triển khai',branches)}<div class="sim-actions"><p><strong>TRY:</strong> tạo tối thiểu hai nhánh chính và một nhánh con.</p><div class="sim-inline"><input id="sim-branch" aria-label="Tên nhánh chính" class="input" placeholder="Tên nhánh chính" style="flex:1">${btn('+ Main Branch','sim-add-main','outline small')}</div><div class="sim-inline item-space"><select id="sim-parent" aria-label="Nhánh cha" class="input">${branches.map((b,i)=>`<option value="${i}">${esc(b.name)}</option>`).join('')}</select><input id="sim-child" aria-label="Tên nhánh con" class="input" placeholder="Tên nhánh con" style="flex:1">${btn('+ Sub Branch','sim-add-child','outline small')}</div>${w.completed?`<div class="sim-notice">✓ Đã thực hành tạo cả main branch và sub-branch.</div>`:''}</div></div>`}
 if(id==='03'){const moved=!!w.moved;v=`<div class="simulator"><div class="sim-toolbar"><span class="sim-caption">SẮP XẾP NODE · kéo thả hoặc dùng nút Chuyển sang Budget</span></div><div class="sim-canvas">${mapVisual('Họp triển khai',[{name:'Timeline',children:moved?['Ngày triển khai: 20/11']:['Ngày triển khai: 20/11','Budget approved']},{name:'Budget',children:moved?['Budget approved']:[]}])}<div class="item-space" style="border-top:1px solid var(--line);padding-top:10px"><span class="stage-counter">KÉO-THẢ NODE</span><div class="sim-inline item-space"><div draggable="true" id="drag-budget" class="node-choice ${moved?'active':''}" title="Kéo node sang Budget">≡ Budget approved</div><div data-drop-budget="yes" class="node-choice" style="border-style:dashed;min-width:130px">→ Thả vào Budget</div></div></div></div><div class="sim-actions"><p><strong>TRY:</strong> di chuyển “Budget approved” từ Timeline sang Budget. Bạn có thể kéo-thả hoặc dùng nút bên dưới.</p>${btn('Chuyển sang Budget','sim-move','outline small')}${moved?`<div class="sim-notice">✓ Node đã được sắp xếp lại; cấu trúc không nhất thiết phải đúng ngay lần đầu.</div>`:''}</div></div>`}
 if(id==='04'){v=`${simMap('Triển khai đào tạo',[{name:'Phê duyệt',children:['Content approval']},{name:'Nội dung',children:['Training materials']}],w.link?'Training materials — ${esc(w.link)} → Content approval':'')}<div class="sim-actions"><p><strong>TRY:</strong> thể hiện rằng tài liệu học phụ thuộc vào phê duyệt nội dung.</p><div class="sim-inline"><select class="input" id="sim-relation" aria-label="Ý nghĩa của mối quan hệ"><option value="depends on">depends on</option><option value="supports">supports</option><option value="blocks">blocks</option></select>${btn('Tạo Relationship','sim-connect','primary small')}</div>${w.link?`<div class="sim-notice">✓ Relationship đã được tạo: ${esc(w.link)}.</div>`:''}</div></div>`}
 if(id==='05'){v=`${simMap('Họp triển khai',[{name:'Finance',children:[{text:'Decision · Budget approved',style:w.decision?'focus':''}]},{name:'Tài liệu',children:[{text:'Action · Mai gửi bản cập nhật',style:w.action?'gold':''}]},{name:'IT',children:['Open Question · Cần tham gia?']}])}<div class="sim-actions"><p><strong>TRY:</strong> dùng tín hiệu thị giác để phân biệt quyết định và hành động.</p><div class="sim-inline">${btn(w.decision?'✓ Decision đã nổi bật':'Làm nổi bật Decision','sim-signal-decision',w.decision?'outline small':'primary small')}${btn(w.action?'✓ Action đã nổi bật':'Làm nổi bật Action','sim-signal-action',w.action?'outline small':'primary small')}</div>${w.completed?`<div class="sim-notice">✓ Hai loại thông tin đã có ký hiệu nhất quán. Không cần dùng thật nhiều màu.</div>`:''}</div></div>`}
 if(id==='06'){v=`<div class="simulator"><div class="sim-toolbar"><span class="sim-caption">CHIA SẺ · chọn quyền phù hợp trước khi sao chép link mô phỏng</span></div><div class="sim-canvas"><div class="share-modal"><strong>Share MindMap</strong><p class="note" style="margin:4px 0 12px">Bản mô phỏng · không sinh link truy cập GitMind thật</p><button class="share-option ${w.permission==='view'?'active':''}" data-action="sim-view">◯ &nbsp; View only</button><button class="share-option ${w.permission==='edit'?'active':''}" data-action="sim-edit">◯ &nbsp; Can edit</button><div class="btn-row">${btn('Copy link (mô phỏng)','sim-copy-link','outline small')}</div></div></div><div class="sim-actions"><p><strong>TRY:</strong> team cần cùng chỉnh sửa sơ đồ. Chọn “Can edit” và mô phỏng thao tác chia sẻ.</p>${w.completed?`<div class="sim-notice">✓ Hoàn tất thao tác mô phỏng chia sẻ. Không có dữ liệu nào được đưa lên GitMind.</div>`:''}</div></div>`}
 return v;
}
const skillChecks={
 '01':{q:'Với tình huống cuộc họp, tên Central Topic nào rõ mục đích nhất?',choices:['Meeting Notes','Họp triển khai đào tạo Q4'],correct:1,why:'Tên cụ thể giúp sơ đồ có định hướng và không bị gom lẫn nhiều nội dung.'},
 '02':{q:'Một thông tin chi tiết thuộc nhánh Budget nên đặt thế nào?',choices:['Là Sub Branch dưới Budget','Luôn tạo thành Central Topic mới'],correct:0,why:'Thông tin thuộc một nhóm chính nên là nhánh con để cấu trúc có ý nghĩa.'},
 '03':{q:'Khi đặt một node nhầm nhóm, bạn nên?',choices:['Xóa cả sơ đồ và làm lại','Di chuyển node sang nhánh phù hợp'],correct:1,why:'MindMap là công cụ tư duy có thể điều chỉnh linh hoạt; cấu trúc đầu tiên không cần hoàn hảo.'},
 '04':{q:'Đường Relationship tốt nhất nên?',choices:['Được đặt nhãn thể hiện mối quan hệ','Nối càng nhiều node càng tốt'],correct:0,why:'Ý nghĩa của liên kết quan trọng hơn số đường vẽ.'},
 '05':{q:'Mục đích ưu tiên của màu/icon trong sơ đồ là?',choices:['Làm tất cả node nổi bật như nhau','Giúp người đọc nhận ra thông tin quan trọng'],correct:1,why:'Signaling nên phục vụ người đọc và phân biệt các loại thông tin.'},
 '06':{q:'Nếu muốn đồng nghiệp cùng chỉnh sửa sơ đồ, bạn sẽ chọn?',choices:['View only','Can edit'],correct:1,why:'Quyền chỉnh sửa cần khớp mục đích cộng tác và chính sách chia sẻ của tổ chức.'}
};
function microView(){const m=C.micros.find(x=>x.id===UI.micro),w=sim(m.id),stage=UI.microStage,k=skillChecks[m.id],selection=w.checkAnswer;
 const steps=[['watch','WATCH · Xem thao tác'],['try','TRY · Thao tác'],['check','CHECK · Củng cố']];
 return `<div class="lab-header"><div><span class="eyebrow">MODULE 03 · 3.${Number(m.id)} / 3.6</span><h2>${esc(m.title)}</h2><p class="subtitle" style="margin-bottom:0">${esc(m.desc)}</p></div></div><div class="stepper">${steps.map((x,i)=>`<button class="step ${stage===x[0]?'active':''} ${i<steps.findIndex(y=>y[0]===stage)?'done':''}" data-action="micro-stage" data-stage="${x[0]}" ${x[0]==='check'&&!w.completed?'disabled':''}><b>${i+1}</b>${x[1]}</button>`).join('')}</div>
 <div class="micro-layout">${stage==='watch'?`<section class="card pad"><div class="watch-heading">▶ WATCH · ${esc(m.skill)}</div>${microVideo(m)}<p class="caption">Micro-tutorial · ${m.seconds}. Xem thao tác rồi luyện ngay trên sơ đồ.</p><div class="context item-space"><strong>Quan sát thao tác</strong><p>${esc(m.desc)} Áp dụng ngay kỹ năng này trong phần TRY.</p></div></section>`:`<details class="video-reference"><summary>▶ Xem lại hướng dẫn · ${esc(m.title)}</summary><div class="video-reference-body">${microVideo(m)}</div></details>`}
 <section class="micro-task">${stage==='watch'?`<div class="try-heading">01 · WATCH</div><h3>Sẵn sàng thử thao tác?</h3><p>Quan sát video, sau đó thực hiện tương tự tại workspace mô phỏng.</p><div class="btn-row">${btn('Chuyển sang TRY →','micro-try')}</div>`:stage==='try'?`<div class="try-heading">02 · TRY · THỰC HÀNH</div><h3>${esc(m.action)}</h3><p>Thao tác trên workspace mô phỏng. Khi làm xong, dùng Check để nhận phản hồi.</p>${microTry(m.id)}<div class="btn-row end">${btn(w.completed?'Tiếp tục đến CHECK →':'Hoàn thành thao tác để mở CHECK →','micro-check','primary',w.completed?'':'disabled')}</div>`:
 `<div class="try-heading">03 · CHECK · TỰ ĐÁNH GIÁ</div><h3>Bạn đã thực hành thao tác</h3><div class="sim-notice">✓ ${esc(m.action)} · Đã ghi nhận thao tác trên simulator.</div><p class="item-space"><strong>${esc(k.q)}</strong></p><div class="options-list">${k.choices.map((o,i)=>`<button class="option-btn ${selection===i?'selected':''} ${w.checkSubmitted?(i===k.correct?'correct':selection===i?'wrong':''):''}" data-action="check-answer" data-value="${i}"><span class="option-letter">${i+1}</span><span>${esc(o)}</span></button>`).join('')}</div>${w.checkSubmitted?`<div class="feedback ${selection===k.correct?'positive':''}"><strong>${selection===k.correct?'✓ Phù hợp':'Cùng xem gợi ý'}</strong><p>${esc(k.why)}</p></div>`:''}<div class="btn-row end">${!w.checkSubmitted?btn('Nhận feedback','check-submit','primary',selection===undefined?'disabled':''):btn('Tiếp tục nội dung tiếp theo →','micro-next','primary')}</div>`}</section></div>
 <div class="btn-row between">${btn('← Nội dung trước','micro-prev','outline',m.id==='01'?'disabled':'')}</div>`;
}
function bindVideo(){document.querySelectorAll('[data-micro-media]').forEach(v=>{const wrap=v.closest('.micro-video');const fallback=wrap.querySelector('.video-placeholder');const fail=()=>{v.style.display='none';fallback.hidden=false;wrap.classList.add('unavailable')};v.addEventListener('error',fail,{once:true});if(v.error)fail();});}
function goMicro(n){const num=Number(n);navigate('micro',{state:{micro:String(Math.max(1,Math.min(6,num))).padStart(2,'0'),microStage:'watch'}})}
function trackMicro(){const w=sim(UI.micro);w.completed=true;save();}
function readField(el){if(el.dataset.field){const id=UI.lab,w=lab(id);if(el.dataset.field.endsWith('-row')){w.rows ||= {};w.rows[el.dataset.index]=el.value}else if(el.dataset.field==='meeting-owner'){w.owner=el.value}else if(el.dataset.field==='meeting-deadline'){w.deadline=el.value}UI.reviewed=false;save();if(el.dataset.field.endsWith('-row')){const focus=el.dataset.index;render();const next=document.querySelector(`[data-field="${id}-row"][data-index="${focus}"]`);if(next)next.focus();}}}
function action(a,el){const id=UI.lab,w=lab(id),m=sim(UI.micro);switch(a){
 case 'open-m1':case 'open-m1video':navigate('m1video');break;case 'open-m1quiz':navigate('m1quiz');break;case 'start-micro':goMicro(1);break;case 'open-m2':navigate('m2');break;case 'open-m3':navigate('m3');break;case 'open-home':navigate('home');break;
 case 'scroll-quiz':navigate('m1quiz');break;
 case 'quiz-answer':P.quiz[UI.quizIndex]=Number(el.dataset.value);save();render();$('#quiz')?.scrollIntoView({block:'start',behavior:'smooth'});break;
 case 'quiz-next':if(UI.quizIndex<4)UI.quizIndex++;else UI.quizResult=true;render();$('#quiz')?.scrollIntoView({block:'start',behavior:'smooth'});break;
 case 'reset-quiz':P.quiz={};UI.quizIndex=0;UI.quizResult=false;save();render();break;
 case 'open-lab':navigate('lab',{state:{lab:el.dataset.id,labStep:0,cardIndex:0,compare:false}});break;
 case 'card-page':UI.cardIndex=Number(el.dataset.index);render();$('.focus-card h3').setAttribute('tabindex','-1');$('.focus-card h3').focus();break;
 case 'card-assign':case 'evidence-assign':{w.rows ||= {};w.rows[Number(el.dataset.index)]=el.dataset.category;UI.reviewed=false;save();if(a==='card-assign'){const missing=C.activities[id].items.findIndex((x,i)=>!w.rows[i]);if(missing>=0)UI.cardIndex=missing;}render();if(a==='card-assign'){message('Đã đặt vào '+el.dataset.category);$('.focus-card h3').setAttribute('tabindex','-1');$('.focus-card h3').focus();}else{document.querySelector(`[data-action="evidence-assign"][data-index="${el.dataset.index}"][data-category="${el.dataset.category}"]`)?.focus();}break;}
 case 'picture-compare':UI.compare=!UI.compare;render();break;
 case 'match-source':UI.matchSource=Number(el.dataset.index);render();document.querySelector('[data-action="match-target"]')?.focus();break;
 case 'match-target':if(UI.matchSource===null)return;w.matches ||= {};w.matches[UI.matchSource]=el.dataset.category;UI.matchSource=null;UI.reviewed=false;save();render();message('Đã nối góc nhìn với tiêu chí');break;
 case 'map-expand':openMap(el);break;
 case 'map-zoom':zoomMap(el,Number(el.dataset.delta));break;
 case 'map-fit':zoomMap(el,0,true);break;
 case 'lab-toggle':{const idx=Number(el.dataset.index);w.selected ||= [];w.selected=w.selected.includes(idx)?w.selected.filter(x=>x!==idx):[...w.selected,idx];UI.reviewed=false;save();render();document.querySelector(`[data-action="lab-toggle"][data-index="${idx}"]`)?.focus();break}
 case 'lab-choice':w.choices ||= {};w.choices[UI.labStep]=Number(el.dataset.index);UI.reviewed=false;save();render();break;
 case 'lab-prev':UI.labStep=Math.max(0,UI.labStep-1);UI.reviewed=false;render();break;
 case 'lab-next':UI.labStep=Math.min(2,UI.labStep+1);UI.reviewed=false;UI.cardIndex=0;render();$('#main').scrollIntoView({block:'start',behavior:'smooth'});break;
 case 'lab-review':UI.reviewed=true;render();break;case 'choose-chip':UI.picked=Number(el.dataset.index);render();break;case 'assign-chip':if(UI.picked===null)return message('Chọn một thẻ thông tin trước');w.rows||={};w.rows[UI.picked]=el.dataset.category;UI.picked=null;UI.reviewed=false;save();render();break;
 case 'lab-finish':P.labs[id]=true;save();message('Đã hoàn thành scenario: '+C.scenarios.find(x=>x.id===id).title);navigate('m2');break;
 case 'open-micro':goMicro(el.dataset.id);break;
 case 'micro-try':UI.microStage='try';render();break;case 'micro-check':if(m.completed){UI.microStage='check';render()}break;case 'micro-stage':if(el.dataset.stage!=='check'||m.completed){UI.microStage=el.dataset.stage;render()}break;case 'check-answer':m.checkAnswer=Number(el.dataset.value);m.checkSubmitted=false;save();render();break;case 'check-submit':if(m.checkAnswer===undefined)return; m.checkSubmitted=true;P.micros[UI.micro]=true;save();render();break;
 case 'micro-prev':goMicro(Number(UI.micro)-1);break;
 case 'micro-next':if(Number(UI.micro)<6)goMicro(Number(UI.micro)+1);else{navigate('m3');message('Đã hoàn thành chuỗi micro learning')};break;
 case 'sim-root-apply':{const input=$('#sim-root');if(!input.value.trim())return message('Hãy nhập tên chủ đề trung tâm');m.root=input.value.trim();trackMicro();render();message('Đã đổi tên Central Topic');break}
 case 'sim-add-main':{const input=$('#sim-branch');if(!input.value.trim())return message('Nhập tên nhánh chính');m.branches||=[{name:'Timeline',children:[]}];m.branches.push({name:input.value.trim(),children:[]});if(m.branches.length>=2&&m.branches.some(x=>x.children?.length))trackMicro();save();render();break}
 case 'sim-add-child':{const input=$('#sim-child'),parent=$('#sim-parent');if(!input.value.trim())return message('Nhập tên nhánh con');m.branches||=[{name:'Timeline',children:[]}];m.branches[Number(parent.value)]?.children.push(input.value.trim());if(m.branches.length>=2&&m.branches.some(x=>x.children?.length))trackMicro();save();render();break}
 case 'sim-move':m.moved=true;trackMicro();render();break;
 case 'sim-connect':m.link=$('#sim-relation').value;m.completed=m.link==='depends on';save();render();if(!m.completed)message('Tài liệu cần được phê duyệt trước: thử nhãn depends on');break;
 case 'sim-signal-decision':m.decision=!m.decision;m.completed=!!(m.decision&&m.action);save();render();break;
 case 'sim-signal-action':m.action=!m.action;m.completed=!!(m.decision&&m.action);save();render();break;
 case 'sim-view':m.permission='view';m.completed=false;m.shared=false;save();render();break;
 case 'sim-edit':m.permission='edit';save();render();break;
 case 'sim-copy-link':if(m.permission!=='edit')return message('Để team cùng chỉnh sửa, hãy chọn Can edit');m.shared=true;trackMicro();render();message('Đã mô phỏng Copy Link (không có link thật)');break;
 }
}
let mapOpener=null;
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('#menu-scrim').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));}
function openMap(el){mapOpener=el;const panel=el.closest('.canvas-panel')||el.closest('.map-surface');$('#expanded-map').innerHTML=panel.outerHTML;$('#expanded-map').querySelector('[data-action="map-expand"]')?.remove();const d=$('#map-dialog');if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','');document.body.classList.add('map-open');$('#map-dialog [data-global-action="close-map"]').focus();}
function closeMap(){const d=$('#map-dialog');if(d?.open){if(typeof d.close==='function')d.close();else d.removeAttribute('open');}document.body.classList.remove('map-open');mapOpener?.focus();mapOpener=null;}
function zoomMap(el,delta,reset=false){const p=el.closest('.canvas-panel'),z=p.querySelector('.zoom-content');const scale=reset?1:Math.max(.55,Math.min(1.9,Number(z.dataset.scale||1)+delta));z.dataset.scale=scale;z.style.zoom=String(scale);p.querySelector('[data-action="map-fit"]').textContent=Math.round(scale*100)+'%';}
$('#map-dialog').addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el)});
$('#map-dialog').addEventListener('close',()=>{document.body.classList.remove('map-open');mapOpener?.focus();mapOpener=null});
$('#screen').addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)action(el.dataset.action,el)});
$('#screen').addEventListener('change',e=>readField(e.target));
$('#screen').addEventListener('input',e=>{if(e.target.dataset.field&&(e.target.dataset.field==='meeting-owner'||e.target.dataset.field==='meeting-deadline')){const w=lab(UI.lab);w[e.target.dataset.field==='meeting-owner'?'owner':'deadline']=e.target.value;save();}});
$('#screen').addEventListener('dragstart',e=>{
 const chip=e.target.closest('[data-drag-chip]');if(chip){UI.picked=Number(chip.dataset.dragChip);e.dataTransfer?.setData('text/plain','chip:'+chip.dataset.dragChip);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';chip.classList.add('dragging');return;}
 if(e.target.id==='drag-budget')e.dataTransfer?.setData('text/plain','budget-approved');
});
$('#screen').addEventListener('dragover',e=>{if(e.target.closest('[data-drop-budget], [data-drop-category]'))e.preventDefault();const z=e.target.closest('[data-drop-category]');if(z)z.classList.add('drag-over')});
$('#screen').addEventListener('dragleave',e=>{const z=e.target.closest('[data-drop-category]');if(z&&!z.contains(e.relatedTarget))z.classList.remove('drag-over')});
$('#screen').addEventListener('drop',e=>{
 const zone=e.target.closest('[data-drop-category]');if(zone){e.preventDefault();const raw=e.dataTransfer?.getData('text/plain')||'';const i=raw.startsWith('chip:')?Number(raw.slice(5)):UI.picked;if(!Number.isInteger(i)||i<0||i>=(C.activities[UI.lab]?.items?.length||0))return;const w=lab(UI.lab);w.rows||={};w.rows[i]=zone.dataset.dropCategory;UI.picked=null;UI.reviewed=false;save();render();return}
 if(e.target.closest('[data-drop-budget]')){e.preventDefault();const m=sim(UI.micro);m.moved=true;trackMicro();render()}
});
document.addEventListener('click',e=>{const a=e.target.closest('[data-global-action]');if(!a)return;const v=a.dataset.globalAction;
 if(v==='close-map')return closeMap();if(v==='back')return back(); if(v==='toggle-nav'){UI.navOpen[a.dataset.id]=!UI.navOpen[a.dataset.id];return renderNav()}
 if(v==='open-current-lab'){UI.stack.push(snapshot());UI.labStep=0;UI.reviewed=false;render();window.scrollTo({top:0,behavior:'instant'});return;} if(v==='noop')return;
 if(v==='open-lab')return navigate('lab',{state:{lab:a.dataset.id,labStep:0,cardIndex:0,compare:false}});
 if(v==='open-micro')return goMicro(a.dataset.id);
 if(v==='open-m1video')return navigate('m1video');if(v==='open-m1quiz')return navigate('m1quiz');
 if(v==='open-home')return navigate('home');if(v==='open-m2')return navigate('m2');if(v==='open-m3')return navigate('m3');
});
$('#menu-toggle').addEventListener('click',()=>setMenu(!$('#sidebar').classList.contains('open')));$('#menu-scrim').addEventListener('click',()=>setMenu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMap();setMenu(false)}});
$('#reset-progress').addEventListener('click',()=>{if(confirm('Xóa tiến độ đã lưu trên trình duyệt này? Video và mã nguồn không bị ảnh hưởng.')){P=defaults();save();UI.quizIndex=0;UI.quizResult=false;UI.labStep=0;UI.microStage='watch';UI.stack=[];navigate('home',{noPush:true});message('Đã đặt lại tiến độ')}});
render();
/* Optional YouTube URLs live in a small JSON file; ordinary MP4 imports need only a matching filename. */
if(typeof fetch==='function'){fetch('assets/videos/video-library.json',{cache:'no-store'}).then(r=>r.ok?r.json():{}).then(v=>{if(v&&typeof v==='object'){VIDEO_CONFIG=v;if(UI.page==='micro')render()}}).catch(()=>{})}
})();
